#define LRU_BUCKETS 10007

struct LRUNode {
  int key;
  int value;
  struct LRUNode *prev;
  struct LRUNode *next;
};

struct LRUEntry {
  int key;
  struct LRUNode *node;
  struct LRUEntry *next;
};

typedef struct {
  int capacity;
  int count;
  struct LRUNode *head; // least recently used
  struct LRUNode *tail; // most recently used
  struct LRUEntry *buckets[LRU_BUCKETS];
} LRUCache;

static unsigned int lruHash(int key) {
  return ((unsigned int)key) % LRU_BUCKETS;
}

static void lruUnlink(LRUCache *cache, struct LRUNode *node) {
  if (node->prev) {
    node->prev->next = node->next;
  } else {
    cache->head = node->next;
  }
  if (node->next) {
    node->next->prev = node->prev;
  } else {
    cache->tail = node->prev;
  }
}

static void lruPushBack(LRUCache *cache, struct LRUNode *node) {
  node->prev = cache->tail;
  node->next = NULL;
  if (cache->tail) {
    cache->tail->next = node;
  } else {
    cache->head = node;
  }
  cache->tail = node;
}

static struct LRUEntry *lruFindEntry(LRUCache *cache, int key) {
  struct LRUEntry *e = cache->buckets[lruHash(key)];
  while (e) {
    if (e->key == key) return e;
    e = e->next;
  }
  return NULL;
}

LRUCache *lRUCacheCreate(int capacity) {
  LRUCache *cache = (LRUCache *)calloc(1, sizeof(LRUCache));
  cache->capacity = capacity;
  cache->count = 0;
  cache->head = NULL;
  cache->tail = NULL;
  return cache;
}

int lRUCacheGet(LRUCache *obj, int key) {
  struct LRUEntry *e = lruFindEntry(obj, key);
  if (!e) return -1;
  lruUnlink(obj, e->node);
  lruPushBack(obj, e->node);
  return e->node->value;
}

void lRUCachePut(LRUCache *obj, int key, int value) {
  struct LRUEntry *e = lruFindEntry(obj, key);
  if (e) {
    e->node->value = value;
    lruUnlink(obj, e->node);
    lruPushBack(obj, e->node);
    return;
  }

  if (obj->count == obj->capacity) {
    struct LRUNode *old = obj->head;
    unsigned int h = lruHash(old->key);
    struct LRUEntry **pp = &obj->buckets[h];
    while (*pp) {
      if ((*pp)->key == old->key) {
        struct LRUEntry *dead = *pp;
        *pp = dead->next;
        free(dead);
        break;
      }
      pp = &(*pp)->next;
    }
    lruUnlink(obj, old);
    free(old);
    obj->count--;
  }

  struct LRUNode *node = (struct LRUNode *)malloc(sizeof(struct LRUNode));
  node->key = key;
  node->value = value;
  lruPushBack(obj, node);

  struct LRUEntry *entry = (struct LRUEntry *)malloc(sizeof(struct LRUEntry));
  entry->key = key;
  entry->node = node;
  unsigned int h = lruHash(key);
  entry->next = obj->buckets[h];
  obj->buckets[h] = entry;
  obj->count++;
}

void lRUCacheFree(LRUCache *obj) {
  struct LRUNode *n = obj->head;
  while (n) {
    struct LRUNode *next = n->next;
    free(n);
    n = next;
  }
  for (int i = 0; i < LRU_BUCKETS; i++) {
    struct LRUEntry *e = obj->buckets[i];
    while (e) {
      struct LRUEntry *next = e->next;
      free(e);
      e = next;
    }
  }
  free(obj);
}

class LRUCache {
  int cap;
  list<pair<int, int>> items; // front = LRU, back = MRU
  unordered_map<int, list<pair<int, int>>::iterator> pos;

public:
  LRUCache(int capacity) : cap(capacity) {}

  int get(int key) {
    auto it = pos.find(key);
    if (it == pos.end()) return -1;
    items.splice(items.end(), items, it->second);
    return it->second->second;
  }

  void put(int key, int value) {
    auto it = pos.find(key);
    if (it != pos.end()) {
      it->second->second = value;
      items.splice(items.end(), items, it->second);
      return;
    }
    if ((int)items.size() == cap) {
      pos.erase(items.front().first);
      items.pop_front();
    }
    items.emplace_back(key, value);
    pos[key] = prev(items.end());
  }
};

type lruEntry struct {
	key   int
	value int
}

type LRUCache struct {
	capacity int
	order    *list.List
	items    map[int]*list.Element
}

func Constructor(capacity int) LRUCache {
	return LRUCache{
		capacity: capacity,
		order:    list.New(),
		items:    make(map[int]*list.Element),
	}
}

func (this *LRUCache) Get(key int) int {
	if el, ok := this.items[key]; ok {
		this.order.MoveToBack(el)
		return el.Value.(*lruEntry).value
	}
	return -1
}

func (this *LRUCache) Put(key int, value int) {
	if el, ok := this.items[key]; ok {
		el.Value.(*lruEntry).value = value
		this.order.MoveToBack(el)
		return
	}
	if this.order.Len() >= this.capacity {
		front := this.order.Front()
		this.order.Remove(front)
		delete(this.items, front.Value.(*lruEntry).key)
	}
	this.items[key] = this.order.PushBack(&lruEntry{key: key, value: value})
}

class LRUCache {
  private final int capacity;
  private final LinkedHashMap<Integer, Integer> map;

  LRUCache(int capacity) {
    this.capacity = capacity;
    this.map = new LinkedHashMap<Integer, Integer>(capacity, 0.75f, true) {
      @Override
      protected boolean removeEldestEntry(Map.Entry<Integer, Integer> eldest) {
        return size() > LRUCache.this.capacity;
      }
    };
  }

  public int get(int key) {
    Integer value = map.get(key);
    return value == null ? -1 : value;
  }

  public void put(int key, int value) {
    map.put(key, value);
  }
}

